describe('Error State Handling', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with your actual page URL
    });

    it('should clear the error message when the user corrects the invalid input', () => {
        cy.get('input#your-input-id') // Replace with your actual input selector
            .type('invalid input')
            .blur(); // Simulate losing focus to trigger validation
        cy.get('.error-message') // Replace with your actual error message selector
            .should('be.visible')
            .and('contain', 'Invalid input'); // Replace with your actual error message text

        cy.get('input#your-input-id')
            .clear()
            .type('valid input') // Replace with valid input
            .blur(); // Trigger validation again
        cy.get('.error-message') // Replace with your actual error message selector
            .should('not.exist'); // Ensure the error message is cleared
    });

    it('should not clear the error message if the input is still invalid', () => {
        cy.get('input#your-input-id') // Replace with your actual input selector
            .type('invalid input')
            .blur(); // Trigger validation
        cy.get('.error-message') // Replace with your actual error message selector
            .should('be.visible');

        cy.get('input#your-input-id')
            .clear()
            .type('another invalid input') // Still invalid input
            .blur(); // Trigger validation again
        cy.get('.error-message') // Replace with your actual error message selector
            .should('be.visible'); // Ensure the error message remains
    });
});
